package com.education.agent.smartcompanion;

import static com.education.agent.smartcompanion.CompanionExperienceService.require;
import com.education.agent.common.error.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.time.OffsetDateTime;
import java.util.*;
import org.springframework.stereotype.Service;

/** Business-owned teaching drafts; model calls never hold the workspace lock. */
@Service
public class CompanionTeachingPlanService {
  final CompanionExperienceService b;
  public CompanionTeachingPlanService(CompanionExperienceService base){b=base;}
  ObjectNode obj(Object... p){return b.obj(p);}
  static ObjectNode defaults(CompanionExperienceService b){return b.obj("objective","","durationMinutes",45,"maxSteps",6);}
  record Target(String scope,String sid,String cid,String nid,Set<String> members){}
  Target target(JsonNode r,JsonNode q){
    String scope=q.path("scopeType").asText(),sid=q.path("studentId").asText(""),cid=q.path("classId").asText(""),nid=q.path("nodeId").asText();
    require(Set.of("STUDENT","CLASS").contains(scope),ErrorCode.VALIDATION_ERROR,"方案目标无效");
    require(b.find(r,"nodes",nid)!=null,ErrorCode.RESOURCE_NOT_FOUND,"请选择单一有效测验");
    var members=new LinkedHashSet<String>();
    if(scope.equals("STUDENT")){var st=b.find(r,"students",sid);require(st!=null,ErrorCode.RESOURCE_NOT_FOUND,"学生不存在");require(cid.isEmpty()||cid.equals(st.path("classId").asText()),ErrorCode.VALIDATION_ERROR,"班级与学生不匹配");cid=st.path("classId").asText();members.add(sid);}
    else {require(sid.isEmpty(),ErrorCode.VALIDATION_ERROR,"班级目标不能指定学生");for(var st:r.path("students"))if(cid.equals(st.path("classId").asText()))members.add(st.path("id").asText());require(!cid.isBlank()&&!members.isEmpty(),ErrorCode.RESOURCE_NOT_FOUND,"班级不存在");}
    return new Target(scope,sid,cid,nid,members);
  }
  ObjectNode plan(ObjectNode state,JsonNode r,Target t){
    ObjectNode p=t.scope.equals("STUDENT")?b.plan(state,t.sid,t.nid,r):state.path("classPlans").has(t.cid+":"+t.nid)?(ObjectNode)state.path("classPlans").path(t.cid+":"+t.nid).deepCopy():obj("revision",0,"dataRevision",state.path("revision"),"status","DRAFT","updatedAt",null,"steps",b.json.createArrayNode());
    p.put("scopeType",t.scope);p.set("studentId",t.scope.equals("STUDENT")?b.json.valueToTree(t.sid):b.json.nullNode());p.put("classId",t.cid);p.put("nodeId",t.nid);if(!p.has("constraints"))p.set("constraints",defaults(b));return p;
  }
  static JsonNode visibleClassPlan(ObjectNode state,JsonNode r,String sid,String nid){
    JsonNode st=null;for(var s:r.path("students"))if(sid.equals(s.path("id").asText()))st=s;
    if(st==null)return null;var p=state.path("classPlans").path(st.path("classId").asText()+":"+nid);
    return p.isObject()&&p.path("status").asText().equals("CONFIRMED")&&p.path("dataRevision").equals(state.path("revision"))?p:null;
  }
  List<JsonNode> records(JsonNode r,Target t){return SmartCompanionEngine.list(r.path("records")).stream().filter(e->t.nid.equals(e.path("nodeId").asText())&&t.members.contains(e.path("studentId").asText())).toList();}
  Set<String> available(JsonNode r,Target t){return CompanionKnowledgeService.ids(b.find(r,"nodes",t.nid).path("availableMaterialIds"),null);}
  List<JsonNode> linked(JsonNode r,Target t,String iid){var available=available(r,t);return SmartCompanionEngine.list(r.path("materials")).stream().filter(m->(available.contains(m.path("id").asText())||!"题目".equals(m.path("type").asText()))&&CompanionKnowledgeService.ids(m.path("indicatorIds"),null).contains(iid)).toList();}
  boolean hasQuestions(JsonNode r,Target t,String iid){return linked(r,t,iid).stream().anyMatch(m->"题目".equals(m.path("type").asText()));}
  ObjectNode summary(JsonNode r,Target t){
    var rs=records(r,t);var sum=b.engine.stats(rs);sum.put("studentCount",t.members.size());sum.put("recordCount",rs.size());var indicators=b.json.createArrayNode();
    for(var i:r.path("indicators")){String iid=i.path("id").asText();Set<String> mids=new HashSet<>();linked(r,t,iid).forEach(m->mids.add(m.path("id").asText()));var es=rs.stream().filter(e->mids.contains(e.path("materialId").asText())).toList();var stats=b.engine.stats(es);var statuses=obj("needs_practice",0,"developing",0,"ready",0,"insufficient",0,"no_evidence",0,"not_assessed",0);int covered=0;for(var o:r.path("observations"))if(t.members.contains(o.path("studentId").asText())&&t.nid.equals(o.path("nodeId").asText())&&iid.equals(o.path("indicatorId").asText())){String key=o.path("status").asText().toLowerCase(Locale.ROOT);statuses.put(key,statuses.path(key).asInt()+1);if(o.path("scoredCount").asInt()>0)covered++;}
      indicators.add(obj("indicatorId",iid,"name",i.path("label"),"scoredCount",stats.path("scoredCount"),"classId",t.cid,"nodeId",t.nid,"studentCount",t.members.size(),"needsPracticeCount",statuses.path("needs_practice").asInt(),"insufficientCount",statuses.path("insufficient").asInt(),"noEvidenceCount",statuses.path("no_evidence").asInt(),"notAssessedCount",statuses.path("not_assessed").asInt(),"availableQuestionCount",linked(r,t,iid).stream().filter(m->"题目".equals(m.path("type").asText())).count(),"coveredStudentCount",covered,"scorePercent",stats.path("scorePercent"),"statusCounts",statuses,"evidenceIds",es.stream().map(e->e.path("id").asText()).limit(100).toList()));}
    sum.set("indicatorSummaries",indicators);return sum;
  }
  ObjectNode constraints(JsonNode c){require(c.isObject()&&c.path("objective").isTextual()&&c.path("objective").asText().length()<=500&&c.path("durationMinutes").isIntegralNumber()&&c.path("durationMinutes").asInt()>=10&&c.path("durationMinutes").asInt()<=180&&c.path("maxSteps").isIntegralNumber()&&c.path("maxSteps").asInt()>=1&&c.path("maxSteps").asInt()<=12,ErrorCode.VALIDATION_ERROR,"目标/时长/步骤约束无效");return obj("objective",c.path("objective"),"durationMinutes",c.path("durationMinutes"),"maxSteps",c.path("maxSteps"));}
  public ObjectNode get(String token,JsonNode input){b.session(token,true);var s=b.state(false);var r=b.report(s);var t=target(r,input);return obj("revision",s.path("revision"),"knowledgeVersion",b.knowledgeVersion(r),"plan",plan(s,r,t),"summary",summary(r,t));}
  Map<String,JsonNode> cards(JsonNode r,Set<String> iids){
    var all=new LinkedHashMap<String,JsonNode>();for(var i:r.path("indicators")){String iid=i.path("id").asText();var c=b.knowledge.learningContent(b.course,iid);if(c!=null)all.put(c.path("knowledgePointId").asText(),c);}
    var selected=new LinkedHashMap<String,JsonNode>();for(String iid:iids){JsonNode card=null;for(var c:all.values())if(iid.equals(c.path("id").asText()))card=c;require(card!=null,ErrorCode.GRAPH_SERVICE_UNAVAILABLE,"审核知识卡未就绪");selected.put(card.path("knowledgePointId").asText(),card);for(var p:card.path("prerequisites")){var pc=all.get(p.path("id").asText());require(pc!=null,ErrorCode.GRAPH_SERVICE_UNAVAILABLE,"前置审核知识未就绪");selected.put(p.path("id").asText(),pc);}}
    for(var c:selected.values())require("APPROVED".equals(c.path("reviewStatus").asText())&&!c.path("sources").isEmpty(),ErrorCode.GRAPH_SERVICE_UNAVAILABLE,"知识事实尚未审核");require(selected.size()<=30,ErrorCode.GRAPH_SERVICE_UNAVAILABLE,"知识卡超过预算");return selected;
  }
  Set<String> stepIndicators(JsonNode steps){var ids=new LinkedHashSet<String>();for(var s:steps)ids.add(s.path("indicatorId").asText());return ids;}
  void refs(JsonNode refs,Set<String> allowed,int limit,ErrorCode code){refs(refs,allowed,limit,code,"references");}
  void refs(JsonNode refs,Set<String> allowed,int limit,ErrorCode code,String field){require(refs.isArray()&&refs.size()<=limit,code,"引用字段 "+field+" 格式或数量无效");for(var ref:refs)require(ref.isTextual()&&allowed.contains(ref.asText()),code,"引用字段 "+field+" 超出目标范围或审核白名单");}
  void validate(JsonNode steps,JsonNode c,JsonNode r,Target t,Map<String,JsonNode> cards,ErrorCode code){
    require(steps.isArray()&&steps.size()<=30,code,"步骤格式无效");var ids=new HashSet<String>();int duration=0;Set<String> kps=cards.keySet(),sources=new HashSet<>();cards.values().forEach(card->card.path("sources").forEach(s->sources.add(s.path("id").asText())));
    Set<String> planMaterials=new HashSet<>();for(String selected:stepIndicators(steps))linked(r,t,selected).forEach(m->planMaterials.add(m.path("id").asText()));
    for(var step:steps){String iid=step.path("indicatorId").asText();require(b.find(r,"indicators",iid)!=null&&hasQuestions(r,t,iid),code,"能力不在本测验测量范围");require(step.path("id").isTextual()&&!step.path("id").asText().isBlank()&&step.path("id").asText().length()<=200&&ids.add(step.path("id").asText()),code,"步骤编号无效");for(String f:List.of("title","action","reason"))require(step.path(f).isTextual()&&step.path(f).asText().length()<=4000,code,"步骤文字无效");
      Set<String> mids=new HashSet<>();linked(r,t,iid).forEach(m->mids.add(m.path("id").asText()));Set<String> eids=new HashSet<>();for(var e:records(r,t))if(mids.contains(e.path("materialId").asText()))eids.add(e.path("id").asText());refs(step.path("materialIds"),planMaterials,100,code,"materialIds");refs(step.path("evidenceIds"),eids,100,code,"evidenceIds");if(step.has("knowledgePointIds"))refs(step.path("knowledgePointIds"),kps,30,code,"knowledgePointIds");if(step.has("sourceIds"))refs(step.path("sourceIds"),sources,80,code,"sourceIds");
      require(step.path("hints").isArray()&&step.path("hints").size()<=20,code,"提示格式无效");for(var h:step.path("hints"))require(h.isTextual()&&h.asText().length()<=2000,code,"提示无效");if(step.has("durationMinutes")){require(step.path("durationMinutes").isIntegralNumber()&&step.path("durationMinutes").asInt()>=1&&step.path("durationMinutes").asInt()<=180,code,"步骤时长无效");duration+=step.path("durationMinutes").asInt();}}
    require(duration<=c.path("durationMinutes").asInt(),code,"步骤总时长超过约束");
  }
  public ObjectNode put(String token,JsonNode input){
    b.session(token,true);var snapshot=b.state(false);var r=b.report(snapshot);var target=target(r,input);var c=constraints(input.path("constraints"));boolean needsKnowledge=false;for(var step:input.path("steps"))if(!step.path("knowledgePointIds").isEmpty()||!step.path("sourceIds").isEmpty())needsKnowledge=true;var cards=needsKnowledge?cards(r,stepIndicators(input.path("steps"))):Map.<String,JsonNode>of();validate(input.path("steps"),c,r,target,cards,ErrorCode.VALIDATION_ERROR);
    return b.tx.execute(tx->{var s=b.state(true);var current=b.report(s);var t=target(current,input);var p=plan(s,current,t);require(input.path("expectedRevision").isIntegralNumber()&&input.path("expectedRevision").asLong()==p.path("revision").asLong()&&input.path("expectedDataRevision").isIntegralNumber()&&input.path("expectedDataRevision").asLong()==s.path("revision").asLong(),ErrorCode.CONCURRENT_MODIFICATION,"方案或数据已变化");require(s.path("revision").equals(snapshot.path("revision")),ErrorCode.CONCURRENT_MODIFICATION,"校验期间数据已变化");require(Set.of("DRAFT","CONFIRMED").contains(input.path("status").asText()),ErrorCode.VALIDATION_ERROR,"方案状态无效");p.put("revision",p.path("revision").asLong()+1);p.set("dataRevision",s.path("revision"));p.set("constraints",c);p.set("steps",input.path("steps").deepCopy());p.set("status",input.path("status"));p.put("updatedAt",OffsetDateTime.now().toString());String field=t.scope.equals("CLASS")?"classPlans":"plans";if(!s.has(field))s.set(field,obj());((ObjectNode)s.path(field)).set((t.scope.equals("CLASS")?t.cid:t.sid)+":"+t.nid,p);b.save(s,false);return p;});
  }
  public ObjectNode generate(String token,JsonNode input){
    b.session(token,true);var s=b.state(false);b.expected(s,input);var r=b.report(s);var t=target(r,input);var p=plan(s,r,t);require(input.path("expectedPlanRevision").isIntegralNumber()&&input.path("expectedPlanRevision").asLong()==p.path("revision").asLong(),ErrorCode.CONCURRENT_MODIFICATION,"方案已变化");var c=constraints(input.path("constraints"));var iids=new LinkedHashSet<String>();require(input.path("indicatorIds").isArray()&&input.path("indicatorIds").size()>=1&&input.path("indicatorIds").size()<=9,ErrorCode.VALIDATION_ERROR,"请选择1至9项能力");for(var id:input.path("indicatorIds"))require(id.isTextual()&&iids.add(id.asText())&&b.find(r,"indicators",id.asText())!=null&&hasQuestions(r,t,id.asText()),ErrorCode.VALIDATION_ERROR,"能力不在本测验范围");require(c.path("maxSteps").asInt()>=iids.size(),ErrorCode.VALIDATION_ERROR,"步骤数必须覆盖每项能力");
    var cards=cards(r,iids);String version=cards.values().iterator().next().path("version").asText();var kps=b.json.createArrayNode();var sources=b.json.createArrayNode();var publicSources=b.json.createArrayNode();var sourceIds=new HashSet<String>();for(var entry:cards.entrySet()){var card=entry.getValue();require(version.equals(card.path("version").asText()),ErrorCode.CONCURRENT_MODIFICATION,"知识卡版本不一致");kps.add(obj("id",entry.getKey(),"name",card.path("name"),"description",card.path("content").asText(card.path("summary").asText())));for(var source:card.path("sources"))if(sourceIds.add(source.path("id").asText())){sources.add(obj("source_id",source.path("id"),"knowledge_point_id",entry.getKey(),"title",source.path("title"),"locator",source.path("location"),"page_from",null,"page_to",null,"excerpt",source.path("excerpt")));publicSources.add(source);}}require(sources.size()<=80,ErrorCode.GRAPH_SERVICE_UNAVAILABLE,"来源超过预算");
    var sum=summary(r,t);var focuses=b.json.createArrayNode();var materials=b.json.createArrayNode();var mids=new HashSet<String>();var focusEvidence=new HashMap<String,Set<String>>();for(var indicator:sum.path("indicatorSummaries"))if(iids.contains(indicator.path("indicatorId").asText())){String iid=indicator.path("indicatorId").asText();JsonNode card=null;for(var card0:cards.values())if(iid.equals(card0.path("id").asText()))card=card0;focuses.add(obj("indicator_id",iid,"name",indicator.path("name"),"knowledge_point_id",card.path("knowledgePointId"),"scored_count",indicator.path("scoredCount"),"available_question_count",indicator.path("availableQuestionCount"),"covered_student_count",indicator.path("coveredStudentCount"),"score_percent",indicator.path("scorePercent"),"status_counts",indicator.path("statusCounts"),"evidence_ids",indicator.path("evidenceIds")));focusEvidence.put(iid,CompanionKnowledgeService.ids(indicator.path("evidenceIds"),null));for(var m:linked(r,t,iid))if(mids.add(m.path("id").asText()))materials.add(obj("material_id",m.path("id"),"type",m.path("type").asText().equals("题目")?"QUESTION":"RESOURCE","body",m.path("body"),"purpose","学习与练习；无直接证据时补充观察"));}require(materials.size()<=60,ErrorCode.VALIDATION_ERROR,"材料超过生成预算，请减少目标能力");
    var request=obj("scope_type",t.scope,"course_id",b.course,"node_id",t.nid,"subject_id",t.scope.equals("CLASS")?t.cid:t.sid,"graph_version",version,"constraints",obj("objective",c.path("objective"),"duration_minutes",c.path("durationMinutes"),"max_steps",c.path("maxSteps")),"summary",obj("student_count",sum.path("studentCount"),"record_count",sum.path("recordCount"),"scored_count",sum.path("scoredCount"),"earned_score",sum.path("earnedScore"),"max_score",sum.path("maxScore"),"score_percent",sum.path("scorePercent")),"focuses",focuses,"knowledge_points",kps,"sources",sources,"materials",materials);
    var response=b.ai.planSmartCompanion(request);ErrorCode code=ErrorCode.AI_SERVICE_INVALID_RESPONSE;require(response!=null&&response.isObject()&&response.toString().length()<=131072,code,"方案响应无效");for(String f:List.of("provider","model","explanation"))require(response.path(f).isTextual()&&!response.path(f).asText().isBlank()&&response.path(f).asText().length()<=(f.equals("explanation")?8000:300),code,"方案响应文字无效");require(response.path("steps").isArray()&&!response.path("steps").isEmpty()&&response.path("steps").size()<=c.path("maxSteps").asInt(),code,"模型步骤数无效");refsCautions(response.path("cautions"),code);var steps=b.json.createArrayNode();var covered=new HashSet<String>();for(var step:response.path("steps")){String iid=step.path("indicator_id").asText();require(iids.contains(iid),code,"模型能力超出范围");covered.add(iid);refs(step.path("evidence_ids"),focusEvidence.get(iid),100,code,"evidence_ids");refs(step.path("material_ids"),mids,60,code,"material_ids");refs(step.path("knowledge_point_ids"),cards.keySet(),30,code,"knowledge_point_ids");refs(step.path("source_ids"),sourceIds,80,code,"source_ids");for(String field:List.of("title","action","rationale"))require(step.path(field).isTextual()&&(field.equals("rationale")||!step.path(field).asText().isBlank())&&step.path(field).asText().length()<=(field.equals("title")?300:field.equals("action")?4000:2000),code,"模型步骤文字无效");for(var ref:step.path("source_ids"))for(var source:sources)if(ref.equals(source.path("source_id")))require(CompanionKnowledgeService.ids(step.path("knowledge_point_ids"),null).contains(source.path("knowledge_point_id").asText()),code,"来源与步骤知识点不匹配");require(step.has("duration_minutes"),code,"缺少步骤时长");steps.add(obj("id","plan-"+UUID.randomUUID(),"title",step.path("title"),"action",step.path("action"),"reason",step.path("rationale"),"indicatorId",iid,"durationMinutes",step.path("duration_minutes"),"knowledgePointIds",step.path("knowledge_point_ids"),"sourceIds",step.path("source_ids"),"materialIds",step.path("material_ids"),"evidenceIds",step.path("evidence_ids"),"hints",step.path("hints")));}require(covered.containsAll(iids),code,"模型未覆盖全部能力");validate(steps,c,r,t,cards,code);
    var current=b.state(false);require(current.path("revision").equals(s.path("revision"))&&plan(current,b.report(current),t).path("revision").equals(p.path("revision")),ErrorCode.CONCURRENT_MODIFICATION,"生成期间数据或方案已变化");for(var card:cards.values()){var now=b.knowledge.learningContent(b.course,card.path("id").asText());require(now!=null&&now.path("version").asText().equals(version),ErrorCode.CONCURRENT_MODIFICATION,"生成期间知识版本已变化");}
    return obj("scopeType",t.scope,"studentId",t.scope.equals("STUDENT")?t.sid:null,"classId",t.cid,"nodeId",t.nid,"dataRevision",s.path("revision"),"basePlanRevision",p.path("revision"),"knowledgeVersion",version,"status","DRAFT","provider",response.path("provider"),"model",response.path("model"),"explanation",response.path("explanation"),"cautions",response.path("cautions"),"constraints",c,"steps",steps,"sources",publicSources);
  }
  void refsCautions(JsonNode values,ErrorCode code){require(values.isArray()&&values.size()<=30,code,"模型提示无效");for(var v:values)require(v.isTextual()&&v.asText().length()<=2000,code,"模型提示无效");}
}
